     1	package shop;
     2	
     3	import java.util.Optional;
     4	
     5	public final class PayOrderHandler implements CommandHandler<PayOrder> {
     6	    private final OrderRepository orders;
     7	
     8	    public PayOrderHandler(OrderRepository orders) {
     9	        this.orders = orders;
    10	    }
    11	
    12	    @Override
    13	    public Result<Order> handle(PayOrder command) {
    14	        Validator validator = new Validator()
    15	                .requireText("orderId", command.orderId())
    16	                .requireMoney("amount", command.amount());
    17	        if (!validator.isValid()) {
    18	            return validator.failure();
    19	        }
    20	        Optional<Order> found = orders.find(command.orderId());
    21	        if (found.isEmpty()) {
    22	            return Result.failure(ErrorCode.NOT_FOUND, "Order " + command.orderId() + " does not exist");
    23	        }
    24	        Order order = found.get();
    25	        if (order.status() != OrderStatus.PLACED) {
    26	            return Result.failure(
    27	                    ErrorCode.INVALID_STATE,
    28	                    "Only placed orders can be paid, but order " + order.id() + " is " + order.status());
    29	        }
    30	        if (command.amount().compareTo(order.total()) > 0) {
    31	            return Result.failure(
    32	                    ErrorCode.INVALID_INPUT,
    33	                    "Payment " + command.amount() + " is more than the order total " + order.total());
    34	        }
    35	        order.markPaid(command.amount());
    36	        orders.save(order);
    37	        return Result.ok(order);
    38	    }
    39	}
