     1	package shop;
     2	
     3	import java.util.HashMap;
     4	import java.util.Map;
     5	
     6	public final class CommandBus {
     7	    private final Map<Class<?>, CommandHandler<?>> handlers = new HashMap<>();
     8	
     9	    public <C> void register(Class<C> commandType, CommandHandler<C> handler) {
    10	        if (handlers.putIfAbsent(commandType, handler) != null) {
    11	            throw new IllegalStateException("Handler already registered for " + commandType.getSimpleName());
    12	        }
    13	    }
    14	
    15	    @SuppressWarnings("unchecked")
    16	    public <C> Result<Order> dispatch(C command) {
    17	        CommandHandler<C> handler = (CommandHandler<C>) handlers.get(command.getClass());
    18	        if (handler == null) {
    19	            return Result.failure(
    20	                    ErrorCode.INVALID_INPUT, "No handler registered for " + command.getClass().getSimpleName());
    21	        }
    22	        return handler.handle(command);
    23	    }
    24	}
