    19	        return new Result<>(Objects.requireNonNull(value), null);
    20	    }
    21	
    22	    public static <T> Result<T> failure(ErrorCode code, String message) {
    23	        return new Result<>(null, new Failure(code, message));
    24	    }
    25	
