     3	import java.math.BigDecimal;
     4	import java.util.ArrayList;
     5	import java.util.List;
     6	
     7	/** Collects the problems of a command's input so that a handler can reject it with one failed result. */
     8	public final class Validator {
     9	    private static final int MONEY_SCALE = 2;
    10	
    11	    private final List<String> problems = new ArrayList<>();
    12	
    13	    public Validator requireText(String field, String value) {
    14	        if (value == null || value.isBlank()) {
    15	            problems.add(field + " must not be blank");
    16	        }
    17	        return this;
    18	    }
    19	
    20	    public Validator requireMoney(String field, BigDecimal value) {
    21	        if (value == null) {
    22	            problems.add(field + " is required");
    23	        } else if (value.signum() <= 0) {
    24	            problems.add(field + " must be greater than zero");
    25	        } else if (value.stripTrailingZeros().scale() > MONEY_SCALE) {
    26	            problems.add(field + " must have at most two decimal places");
    27	        }
    28	        return this;
    29	    }
    30	
    31	    public boolean isValid() {
    32	        return problems.isEmpty();
    33	    }
    34	
    35	    public <T> Result<T> failure() {
    36	        return Result.failure(ErrorCode.INVALID_INPUT, String.join("; ", problems));
    37	    }
    38	}
